public partial class Studio {
 static bool Finite(double v){return !double.IsNaN(v)&&!double.IsInfinity(v);}
 void ValidateMontage(MontageDocument d,bool files){
  if(d==null||d.Version!=1||d.Assets==null||d.Tracks==null||d.Items==null||d.Items.Count>80||d.Tracks.Count>24||d.Assets.Count>500||d.Aspect<0||d.Aspect>2||d.Resolution<0||d.Resolution>1||(d.Fps!=30&&d.Fps!=60))throw new Exception("Повреждённый проект дорожек.");
  var ids=new HashSet<string>();foreach(var a in d.Assets){if(String.IsNullOrEmpty(a.Id)||!ids.Add(a.Id)||String.IsNullOrEmpty(a.Path)||(a.Kind!="video"&&a.Kind!="image"&&a.Kind!="audio")||!Finite(a.Duration)||a.Duration<=0)throw new Exception("Некорректный медиафайл проекта.");if(files&&!File.Exists(a.Path))throw new Exception("Файл не найден: "+a.Path);}
  ids.Clear();foreach(var t in d.Tracks)if(String.IsNullOrEmpty(t.Id)||!ids.Add(t.Id)||(t.Kind!="video"&&t.Kind!="audio"&&t.Kind!="text"))throw new Exception("Некорректная дорожка.");
  ids.Clear();foreach(var c in d.Items){var t=d.Tracks.FirstOrDefault(v=>v.Id==c.Track);var a=d.Assets.FirstOrDefault(v=>v.Id==c.Asset);if(String.IsNullOrEmpty(c.Id)||!System.Text.RegularExpressions.Regex.IsMatch(c.Id,"^[a-f0-9]{32}$")||!ids.Add(c.Id)||t==null||(t.Kind!="text"&&(a==null||(t.Kind=="audio")!=(a.Kind=="audio"))))throw new Exception("Клип ссылается на недоступную дорожку или файл.");
   double[] nums={c.Start,c.In,c.Length,c.Speed,c.Volume,c.X,c.Y,c.Scale,c.Rotation,c.Opacity,c.Font,c.Fade};if(nums.Any(v=>!Finite(v))||c.Start<0||c.In<0||c.Length<.099999||c.Start+c.Length>86400||c.Speed<.5||c.Speed>2||c.Volume<0||c.Volume>200||c.X<0||c.X>100||c.Y<0||c.Y>100||c.Scale<10||c.Scale>500||c.Rotation< -180||c.Rotation>180||c.Opacity<0||c.Opacity>100||c.Font<16||c.Font>160||c.Fade<0||c.Fade>2||c.Mask<0||c.Mask>3||c.Filter<0||c.Filter>5||c.Style<0||c.Style>5||(c.Text??"").Length>10000)throw new Exception("Некорректные параметры клипа.");
   if(a!=null&&a.Kind!="image"&&c.In+c.Length*c.Speed>a.Duration+.003)throw new Exception("Клип выходит за длительность исходника: "+Path.GetFileName(a.Path));
  }
 }
 string MontageStyle(MontageClip c,int w){int font=Math.Max(8,(int)Math.Round(c.Font*w/1080*c.Scale/100));string style=c.Style==1?"fontcolor=yellow:borderw=3:bordercolor=black":c.Style==2?"fontcolor=white:box=1:boxcolor=0x713EDB@0.9:boxborderw=14":c.Style==3?"fontcolor=white:box=1:boxcolor=black@0.75:boxborderw=14":c.Style==4?"fontcolor=0x57F0FF:borderw=2:bordercolor=0x222236":c.Style==5?"fontcolor=white":"fontcolor=white:borderw=3:bordercolor=black";return "drawtext=fontfile=font.ttf:textfile=text-"+c.Id+".txt:expansion=none:fontsize="+font+":"+style+":x=(w-text_w)/2:y=(h-text_h)/2";}
 string MontageColor(int index){return index==1?",eq=contrast=1.18:saturation=0.85":index==2?",colorbalance=rs=0.12:bs=-0.08":index==3?",colorbalance=rs=-0.08:bs=0.15":index==4?",hue=s=0":index==5?",eq=saturation=1.45:contrast=1.05":"";}
 string MontageMaskFilter(int mask){if(mask==0)return "";string expression=mask==3?"if(lte(pow(max(abs(X-W/2)-(W/2-min(W,H)*0.15),0),2)+pow(max(abs(Y-H/2)-(H/2-min(W,H)*0.15),0),2),pow(min(W,H)*0.15,2)),255,0)":"if(lte(pow((X-W/2)/(W/2),2)+pow((Y-H/2)/(H/2),2),1),255,0)";return ",geq=r='r(X,Y)':g='g(X,Y)':b='b(X,Y)':a='alpha(X,Y)*("+expression+")/255'";}
 async Task<RunResult> RenderMontage(MontageDocument d,string output,bool preview,bool still,double from,double length,Action<Process> started,Action<double> progress){
  ValidateMontage(d,true);int w,h;Dimensions(new EditSettings{Aspect=d.Aspect,Resolution=d.Resolution},preview,out w,out h);length=Math.Max(1.0/d.Fps,Math.Min(length,Math.Max(1.0/d.Fps,d.Duration-from)));
  string job=Path.Combine(cacheRoot,Id());Directory.CreateDirectory(job);string partial=still?output:Path.Combine(Path.GetDirectoryName(output),Path.GetFileNameWithoutExtension(output)+"_"+Id().Substring(0,6)+".partial.mp4");
  var args=new StringBuilder("-hide_banner -loglevel warning -nostdin -y -threads 2 -filter_complex_threads 1 -progress pipe:1 -stats_period 0.5 -f lavfi -i "+Q("color=c=black:s="+w+"x"+h+":r="+d.Fps+":d="+N(length))+" ");var fs=new List<string>();fs.Add("[0:v]format=rgba[base0]");int input=1,layer=0,audio=0;var audioNames=new List<string>();
  try{
   File.Copy(Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.Fonts),"segoeuib.ttf"),Path.Combine(job,"font.ttf"),true);
   foreach(var track in d.Tracks.AsEnumerable().Reverse()){
    foreach(var clip in d.Items.Where(c=>c.Track==track.Id&&c.Start+c.Length>from&&c.Start<from+length)){
     var asset=d.Assets.FirstOrDefault(a=>a.Id==clip.Asset);double cut=Math.Max(0,from-clip.Start),begin=Math.Max(0,clip.Start-from),len=Math.Min(clip.Start+clip.Length,from+length)-Math.Max(clip.Start,from);int index=-1;
     bool visible=track.Kind!="audio"&&!track.Hidden;bool audible=!still&&!track.Hidden&&!track.Muted&&asset!=null&&asset.Audio&&clip.Volume>0;
     if(!visible&&!audible)continue;
     if(asset!=null){index=input++;if(asset.Kind=="image")args.Append("-loop 1 -framerate "+d.Fps+" -t "+N(len*clip.Speed)+" -i "+Q(asset.Path)+" ");else args.Append("-ss "+N(clip.In+cut*clip.Speed)+" -t "+N(len*clip.Speed)+" -i "+Q(asset.Path)+" ");}
     if(visible){string chain;
      if(track.Kind=="text"){File.WriteAllText(Path.Combine(job,"text-"+clip.Id+".txt"),clip.Text??"",new UTF8Encoding(false));chain="color=c=black@0:s="+w+"x"+h+":r="+d.Fps+":d="+N(len)+",format=rgba,"+MontageStyle(clip,w);}
      else {int scale=Math.Max(2,(int)Math.Round(w*clip.Scale/100/2)*2);chain="["+index+":v:0]setpts=(PTS-STARTPTS)/"+N(clip.Speed)+",fps="+d.Fps+(clip.Mask==1?",crop='min(iw,ih)':'min(iw,ih)'":"")+",scale="+scale+":-2,setsar=1,format=rgba"+MontageColor(clip.Filter)+MontageMaskFilter(clip.Mask);}
      chain+=",colorchannelmixer=aa="+N(clip.Opacity/100);double fade=Math.Min(clip.Fade,clip.Length/2);if(fade>0)chain+=",setpts=PTS+"+N(cut)+"/TB,fade=t=in:st=0:d="+N(fade)+":alpha=1,fade=t=out:st="+N(clip.Length-fade)+":d="+N(fade)+":alpha=1,setpts=PTS-STARTPTS";
      if(Math.Abs(clip.Rotation)>.001){string angle=N(clip.Rotation*Math.PI/180);chain+=",rotate="+angle+":ow=rotw("+angle+"):oh=roth("+angle+"):c=black@0";}
      chain+=",setpts=PTS+"+N(begin)+"/TB[layer"+layer+"]";fs.Add(chain);fs.Add("[base"+layer+"][layer"+layer+"]overlay=x=W*"+N(clip.X/100)+"-w/2:y=H*"+N(clip.Y/100)+"-h/2:eof_action=pass:repeatlast=0:enable='between(t,"+N(begin)+","+N(begin+len)+")'[base"+(layer+1)+"]");layer++;
     }
     if(audible){string label="sound"+audio++;string chain="["+index+":a:0]asetpts=PTS-STARTPTS,atempo="+N(clip.Speed)+",aresample=48000,aformat=sample_fmts=fltp:channel_layouts=stereo,atrim=duration="+N(len)+",volume="+N(clip.Volume/100);double fade=Math.Min(clip.Fade,clip.Length/2);if(fade>0)chain+=",asetpts=PTS+"+N(cut)+"/TB,afade=t=in:st=0:d="+N(fade)+",afade=t=out:st="+N(clip.Length-fade)+":d="+N(fade)+",asetpts=PTS-STARTPTS";chain+=",adelay="+(int)Math.Round(begin*1000)+"|"+(int)Math.Round(begin*1000)+"["+label+"]";fs.Add(chain);audioNames.Add("["+label+"]");}
    }
   }
   fs.Add("[base"+layer+"]format=yuv420p[outv]");if(audioNames.Count>0)fs.Add(String.Join("",audioNames)+"amix=inputs="+audioNames.Count+":duration=longest:dropout_transition=0:normalize=0,apad,atrim=duration="+N(length)+",alimiter=limit=0.95:level=0:latency=1[outa]");
   string script=Path.Combine(job,"filters.txt");File.WriteAllText(script,String.Join(";\n",fs),new UTF8Encoding(false));args.Append("-/filter_complex "+Q(script)+" -map [outv] "+(audioNames.Count>0?"-map [outa] ":"")+(still?"-frames:v 1 -update 1 ":"-t "+N(length)+" -c:v libx264 -threads 2 -preset "+(preview?"ultrafast -crf 27":"veryfast -crf 20")+" -pix_fmt yuv420p -c:a aac -b:a 192k -movflags +faststart ")+Q(partial));
   var result=await Run(ffmpeg,args.ToString(),job,started,line=>{if(line.StartsWith("out_time_us=")&&progress!=null){double v;if(double.TryParse(line.Substring(12),out v))progress(Math.Min(99.9,Math.Max(0,v/1000000/length*100)));}});if(result.Code==0&&!still){if(File.Exists(output))File.Replace(partial,output,null);else File.Move(partial,output);}return result;
  }finally{CleanJob(job);}
 }
 void StopMontagePlayer(){bool wasPlaying=montagePlaying;montagePlayback.Stop();montagePlaying=false;montagePlayer.Stop();montagePlayer.Close();montagePlayer.Visibility=Visibility.Collapsed;montageImage.Visibility=Visibility.Visible;CleanJob(montagePreviewJob);montagePreviewJob=null;if(wasPlaying)RequestMontageFrame();}
 async Task RenderMontageFrame(){if(!montageMode||exporting||previewBuilding||montagePreviewBusy||montagePlaying)return;montagePreviewBusy=true;montageFramePending=false;string job=Path.Combine(cacheRoot,Id());Directory.CreateDirectory(job);try{string path=Path.Combine(job,"frame.png");var snapshot=new JavaScriptSerializer().Deserialize<MontageDocument>(MontageSnapshot());var r=await RenderMontage(snapshot,path,true,true,Math.Min(montageSeek.Value,Math.Max(0,montage.Duration-.04)),.1,null,null);if(r.Code!=0)throw new Exception(Tail(r.Error,400));montageImage.Source=ReadBitmap(path);}catch(Exception ex){Status("Кадр дорожек: "+ex.Message);}finally{montagePreviewBusy=false;CleanJob(job);if(montageFramePending)RequestMontageFrame();}}
 async Task PlayMontage(){if(previewBuilding){previewCancelRequested=true;Kill(previewProcess);return;}if(montagePlaying){StopMontagePlayer();return;}if(exporting||montage.Items.Count==0)return;StopMontagePlayer();montagePreviewJob=Path.Combine(cacheRoot,Id());Directory.CreateDirectory(montagePreviewJob);string path=Path.Combine(montagePreviewJob,"play.mp4");previewBuilding=true;previewCancelRequested=false;try{double from=Math.Min(montageSeek.Value,Math.Max(0,montage.Duration-.1));Status("Подготовка предпросмотра дорожек… повторное нажатие отменяет.");var snapshot=new JavaScriptSerializer().Deserialize<MontageDocument>(MontageSnapshot());var r=await RenderMontage(snapshot,path,true,false,from,Math.Min(20,montage.Duration-from),p=>{previewProcess=p;if(previewCancelRequested)Kill(p);},null);if(previewCancelRequested)return;if(r.Code!=0)throw new Exception(Tail(r.Error,600));montagePlayer.Source=new Uri(path);montagePlayer.Visibility=Visibility.Visible;montageImage.Visibility=Visibility.Collapsed;montagePlayer.Volume=1;montagePlayer.Play();montagePlaying=true;montagePlaybackFrom=from;montagePlayback.Start();Status("Предпросмотр до 20 секунд от курсора с масками, текстами и звуком.");}catch(Exception ex){Status(ex.Message);}finally{previewBuilding=false;previewProcess=null;if(!montagePlaying)StopMontagePlayer();}}
 async Task ExportMontage(){if(exporting||previewBuilding||montage.Items.Count==0)return;ValidateMontage(montage,true);var d=new SaveFileDialog{Filter="Видео MP4|*.mp4",DefaultExt=".mp4",FileName="Монтаж_sliks37.mp4"};if(d.ShowDialog(window)!=true)return;if(!String.Equals(Path.GetExtension(d.FileName),".mp4",StringComparison.OrdinalIgnoreCase))throw new Exception("Укажите расширение .mp4.");if(montage.Assets.Any(a=>String.Equals(Path.GetFullPath(a.Path),Path.GetFullPath(d.FileName),StringComparison.OrdinalIgnoreCase)))throw new Exception("Выберите другое имя, чтобы сохранить исходник.");exporting=true;exportCancelRequested=false;StopMontagePlayer();Btn("CancelExport").IsEnabled=true;Btn("Export").IsEnabled=false;Bar("TaskProgress").Visibility=Visibility.Visible;Bar("TaskProgress").Value=0;try{var snapshot=new JavaScriptSerializer().Deserialize<MontageDocument>(MontageSnapshot());var r=await RenderMontage(snapshot,d.FileName,false,false,0,snapshot.Duration,p=>{exportProcess=p;if(exportCancelRequested)Kill(p);},v=>Dispatch(()=>{Bar("TaskProgress").Value=v;Status("Экспорт дорожек: "+v.ToString("0.0")+"%");}));if(r.Code!=0)throw new Exception(exportCancelRequested?"Экспорт отменён. Частичный файл имеет суффикс .partial.mp4.":Tail(r.Error,800));Bar("TaskProgress").Value=100;Status("Монтаж сохранён: "+d.FileName);Process.Start("explorer.exe","/select,"+Q(d.FileName));}catch(Exception ex){Status(ex.Message);}finally{exporting=false;exportProcess=null;Btn("Export").IsEnabled=true;Btn("CancelExport").IsEnabled=false;}}
}
